option.value:
body {
    background: #f0f0f0;
    font-family: Arial, sans-serif;
}

.login-container {
    max-width: 26rem;
    margin: 4rem auto;
    background: var(--secondary-bg);
    border-radius: 1.25rem;
    box-shadow: var(--shadow-main);
    padding: 2rem 1.5rem 1.5rem 1.5rem;
    color: var(--text-main);
    border: 0.125rem solid var(--border-main);
}

h2 {
    color: var(--text-accent);
    text-align: center;
    margin-bottom: 1.25rem;
    letter-spacing: 0.125rem;
}

label {
    display: block;
    margin-top: 1rem;
    font-weight: bold;
}

input[type="text"],
input[type="password"] {
    width: 100%;
    margin-top: 0.375rem;
    padding: 0.5rem;
    border-radius: 0.5rem;
    border: 0.125rem solid var(--input-border);
    background: var(--input-bg);
    color: var(--text-main);
    font-size: 1rem;
}

button {
    margin-top: 1.5rem;
    width: 100%;
    padding: 0.75rem 0;
    border-radius: 0.75rem;
    font-size: 1.1rem;
    background: #0078d7;
    color: #fff;
    border: none;
    cursor: pointer;
}

button:hover {
    background: #005fa3;
}

.error {
    color: #d32f2f;
    margin-top: 0.75rem;
}

.back-link {
    display: block;
    margin-top: 1.125rem;
    text-align: center;
    color: var(--text-accent);
    text-decoration: underline;
    cursor: pointer;
}

@media (max-width: 600px) {
    .login-container {
        max-width: 98vw;
        padding: 1.25rem 0.5rem 1rem 0.5rem;
    }
}

